declare @acc nvarchar(1024), @cus nvarchar(1024), @bi_ten_tk nvarchar(1024), @bi_ten_tk2 nvarchar(1024), @bi_ten_vv nvarchar(1024), @bi_ten_vv2 nvarchar(1024)
select @acc = case when upper(@@language) = 'V' then ten_tk else ten_tk2 end from dmtk where tk = @tk
if @acc <> '' select @acc = '- ' + @acc
select @cus = case when upper(@@language) = 'V' then ten_vv else ten_vv2 end from dmvv where ma_vv = @ma_vv
if @cus <> '' select @cus = '- ' + @cus
select @bi_ten_tk = ten_tk, @bi_ten_tk2 = ten_tk2  from dmtk where tk = @tk
select @bi_ten_vv = ten_vv, @bi_ten_vv2 = ten_vv2 from dmvv where ma_vv = @ma_vv
select @ngay_ht1 as date_from, @ngay_ht2 as date_to, @tk as tk, @acc as ten_tk, @ma_vv as ma_vv, @cus as ten_vv, @bi_ten_tk as bi_ten_tk, @bi_ten_tk2 as bi_ten_tk2, @bi_ten_vv as bi_ten_vv, @bi_ten_vv2 as bi_ten_vv2
exec zrs_rptJobCateDebtComparisonBook @tk, @ma_vv, @ma_td3, @ma_kh, @ngay_ht1, @ngay_ht2, @ma_dvcs, @@language, @@userID, @@admin









