function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	if (f._convection) f._convection = null;
	else {
		changeLookupReadonly(f, 'ma_dvcs');
		var a = ['tk', 'ma_vv', 'ma_td3'];
		if (!f._extensions) f.request('GetDefaultValue', 'SetDefaultValue', a);
			else setReferenceValue(f, a);
	}
	&ReportSign.Filter.Active;
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
	try {f._tabContainer.remove_activeTabChanged(onChange$VoucherFilter$Tab);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, x = f.getItemValue('mau_bc'), s3 = f.getItem('ten_vv%l').value, s5 = f.getItemValue('ten_dtqt%l');
			var d1 = f.getItem('ngay_ht1').value, d2 = f.getItem('ngay_ht2').value;
			var detail = '0', balance = '1'
			if (s3 != '') s3 = ' - ' + s3;
			if (s5 != '') s5 = ' - ' + s5
			g._alterTitle = [null, [['%d1', d1, true], ['%d2', d2, true], ['%s1', f.getItem('tk').value, true], ['%s2', f.getItem('ma_vv').value, true], ['%s3', s3, true], ['%s4', f.getItem('ma_td3').value, true], ['%s5', s5, true]]];
			g._hiddenFields = [
				{Fields: 'so_luong', Value: (detail == '0')},
				{Fields: 'gia, tien', Value: (x == '20' || detail == '0')},
				{Fields: 'gia_nt, tien_nt', Value: (x == '10' || detail == '0')},
				{Fields: 'du_no, du_co', Value: (balance == '0')},
				{Fields: 'du_no_nt, du_co_nt', Value: (x == '10' || balance == '0')},
				{Fields: 'ps_no_nt, ps_co_nt, ma_nt, ty_gia', Value: (x == '10')}
				];
			g._hiddenForms = [
				{Form: [0, 1, 2, 3, 6, 7, 8, 9, 13, 14, 15, 16, 19, 20, 21, 22], Value: (detail == '1')},
				{Form: [2, 3, 4, 5, 8, 9, 10, 11, 15, 16, 17, 18, 21, 22, 23, 24], Value: (balance == '0' && detail == '0')},
				{Form: [0, 1, 4, 5, 6, 7, 10, 11, 13, 14, 17, 18, 19, 20, 23, 24], Value: (balance == '1' && detail == '0')}
			];
			remove$GridReport$Filter(g);
			break;
		case 'SetDefaultValue':
			f.setItemControlBehavior('ten_tk%l', result[0].Value, null, true);
			f.setItemControlBehavior('ten_vv%l', result[2].Value, null, true);
			f.setItemControlBehavior('ten_dtqt%l', result[4].Value, null, true);
			if (result[1].Value) f.setItemValue('tk', '');
			if (result[3].Value) f.setItemValue('ma_vv', '');
			if (result[5].Value) f.setItemValue('ma_td3', '');
			break;
		default:
			break;
	}
}
function setReferenceValue(f, a) {
	for (var i = 0; i < a.length; i++) {
		var r = $func.findField(a[i], f._fields).ItemReference;
		f.setItemValue(r, $func.findMemvar(r, f._extensions).NewValue);
	}
}
/* </flatten> */







declare @c0 nvarchar(1024), @c1 nvarchar(1024), @c2 nvarchar(1024)
select @c0 = ten_tk%l from dmtk where tk = @tk
select @c1 = ten_vv%l from dmvv where ma_vv = @ma_vv
select @c2 = ten_dtqt%l from dmdtqt3 where ma_dtqt = @ma_td3
select isnull(@c0, '') as c0, cast(case when @c0 is null then 1 else 0 end as bit) as c1, isnull(@c1, '') as c2, cast(case when @c1 is null then 1 else 0 end as bit) as c3
	, cast(case when @c2 is null then 1 else 0 end as bit) as c4, isnull(@c2, '') as c5
return





